import { adventures } from './data.js';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const root=$('#adventurePageGrid'),modal=$('#modal'),content=$('#modalContent');
root.innerHTML=adventures.map((a,index)=>`<button class="adventure-page-card" type="button" data-adventure="${esc(a.id)}">${a.art?`<img src="assets/${esc(a.art)}" alt="" loading="lazy" />`:`<span class="adventure-page-icon">${['🐚','🫧','🔎','🪸'][index%4]}</span>`}<span><small>Misja ${index+1}</small><strong>${esc(a.title)}</strong><p>${esc(a.short||a.description||'')}</p><b>Otwórz przygodę →</b></span></button>`).join('');
root.addEventListener('click',event=>{const button=event.target.closest('[data-adventure]');if(!button)return;const a=adventures.find(x=>x.id===button.dataset.adventure);if(!a)return;content.innerHTML=`<article class="adventure-reader"><p class="kicker">Przygoda Dorszolandii</p><h2>${esc(a.title)}</h2><p>${esc(a.full||a.description||a.short||'')}</p>${Array.isArray(a.steps)&&a.steps.length?`<h3>Kroki misji</h3><ol>${a.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`:''}</article>`;if(!modal.open)modal.showModal();});
